using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> => Type: {personInfo.Type.Name}, Properties: {personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type that IS resolvable (default reflection resolver handles it)
if (options.TryGetTypeInfo<Person>(out var resolved))
    Console.WriteLine($"TryGet Person  => resolved ({resolved!.Type.Name})");
else
    Console.WriteLine("TryGet Person  => not available");

// 2b. Type that is NOT resolvable (custom resolver that knows nothing)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (limited.TryGetTypeInfo<Person>(out var missing))
    Console.WriteLine($"TryGet Person (empty resolver) => resolved ({missing!.Type.Name})");
else
    Console.WriteLine("TryGet Person (empty resolver) => not available (as expected)");

// --- helpers ---
public record Person(string Name, int Age);

/// A resolver that deliberately resolves nothing.
public sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

