+
+// 2b. Type that is NOT resolvable (custom resolver that knows nothing)
+var limited = new JsonSerializerOptions
+{
+    TypeInfoResolver = new EmptyResolver()
+};
+
+if (limited.TryGetTypeInfo<Person>(out var missing))
+    Console.WriteLine($"TryGet Person (empty resolver) => resolved ({missing!.Type.Name})");
+else
+    Console.WriteLine("TryGet Person (empty resolver) => not available (as expected)");
+
+// --- helpers ---
+public record Person(string Name, int Age);
+
+/// A resolver that deliberately resolves nothing.
+public sealed class EmptyResolver : IJsonTypeInfoResolver
+{
+    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
